// Live pipeline: no automated review runs here. The version is labeled as unreviewed, never as approved.
const sub = $('Log to Supabase').first().json;
if (!sub || !sub.id) throw new Error('No submission id. No plan version was created.');
const rows = $input.all().map((i) => i.json).filter((r) => r && r.version);
const version = rows.reduce((m, r) => Math.max(m, Number(r.version) || 0), 0) + 1;
const pdf = $('Generate PDF').first().binary;
if (!pdf || !pdf.pdf_data) throw new Error('Generate PDF returned no file. No plan version was created.');
const body = $('Webhook').first().json.body || {};
const formEmail = String(body.email || '').trim();
const checkoutEmail = String(body.verifiedEmail || '').trim();
const emailNote = checkoutEmail && checkoutEmail.toLowerCase() !== formEmail.toLowerCase()
  ? ' Checkout email (' + checkoutEmail + ') differs from the form email (' + formEmail + '). Delivery goes to the form email.'
  : '';
return [{
  json: {
    submission_id: sub.id,
    version,
    pdf_path: sub.id + '/v' + version + '.pdf',
    review_status: 'NO MACHINE REVIEW',
    review_notes: 'No automated review ran on this plan. Nothing in it has been checked by machine. Read the PDF in full before approving.' + emailNote,
  },
  binary: { pdf_data: { ...pdf.pdf_data, mimeType: 'application/pdf' } },
}];
